import Redis from 'ioredis'

// ---------------------------------------------------------------------------
// Singleton ioredis client
// ---------------------------------------------------------------------------

let _client: Redis | null = null

function createClient(): Redis {
  const client = new Redis({
    host: process.env.REDIS_HOST ?? 'localhost',
    port: parseInt(process.env.REDIS_PORT ?? '6379', 10),
    password: process.env.REDIS_PASSWORD || undefined,
    db: parseInt(process.env.REDIS_DB ?? '0', 10),
    lazyConnect: true,
    maxRetriesPerRequest: 3,
    enableReadyCheck: true,
    enableOfflineQueue: false,
    connectTimeout: 10_000,
    commandTimeout: 5_000,
    retryStrategy: (times) => Math.min(times * 100, 3_000),
  })
  client.on('error', (err: Error) => {
    console.error('[examiner/redis] error:', err.message)
  })
  return client
}

export function getRedis(): Redis {
  if (!_client) _client = createClient()
  return _client
}

// ---------------------------------------------------------------------------
// TimerState — anchor-based, zero writes while clock is running.
//
// remaining = durationSeconds − consumedSeconds
//           − (RUNNING ? floor((now − startEpochMs) / 1000) : 0)
// ---------------------------------------------------------------------------

export type TimerStatus = 'RUNNING' | 'PAUSED' | 'STOPPED'

export interface TimerState {
  startEpochMs: number | null   // epoch when current RUNNING period began
  durationSeconds: number        // total time for this entity
  consumedSeconds: number        // seconds used in prior RUNNING periods
  status: TimerStatus
  updatedAt: number
}

export function computeRemaining(state: TimerState): number {
  const runningElapsed =
    state.status === 'RUNNING' && state.startEpochMs !== null
      ? Math.floor((Date.now() - state.startEpochMs) / 1000)
      : 0
  return Math.max(0, state.durationSeconds - state.consumedSeconds - runningElapsed)
}

// ---------------------------------------------------------------------------
// Key scheme (two namespaces, same TimerState shape):
//
//   flextest:exam:session:{sessionId}
//     → The session-level clock, set when examiner starts the session.
//       Used ONLY for examiner display (elapsed / remaining for the session).
//
//   flextest:exam:timer:{sessionId}:{candidateId}
//     → Per-candidate clock, anchored at the moment THAT candidate started
//       their exam. This is what feeds the DB sync and the candidate's display.
//
// The two clocks are independent. If a candidate joins 15 min late their
// timer still starts from durationSeconds; they don't lose 15 minutes.
// ---------------------------------------------------------------------------

const SESSION_KEY = (sid: string) => `flextest:exam:session:${sid}`
const CANDIDATE_KEY = (sid: string, cid: string) => `flextest:exam:timer:${sid}:${cid}`
const CANDIDATE_SCAN_PATTERN = (sid: string) => `flextest:exam:timer:${sid}:*`
const ALL_CANDIDATES_SCAN_PATTERN = 'flextest:exam:timer:*'

// ---------------------------------------------------------------------------
// Session-level helpers (examiner display)
// ---------------------------------------------------------------------------

export async function getSessionState(sessionId: string): Promise<TimerState | null> {
  try {
    const raw = await getRedis().get(SESSION_KEY(sessionId))
    if (!raw) return null
    return JSON.parse(raw) as TimerState
  } catch {
    return null
  }
}

export async function setSessionState(
  sessionId: string,
  state: TimerState
): Promise<void> {
  const ttl = state.durationSeconds + 7_200
  await getRedis().set(
    SESSION_KEY(sessionId),
    JSON.stringify(state),
    'EX',
    Math.max(ttl, 7_200)
  )
}

// ---------------------------------------------------------------------------
// Per-candidate timer helpers
// ---------------------------------------------------------------------------

export async function getTimerState(
  sessionId: string,
  candidateId: string
): Promise<TimerState | null> {
  try {
    const raw = await getRedis().get(CANDIDATE_KEY(sessionId, candidateId))
    if (!raw) return null
    return JSON.parse(raw) as TimerState
  } catch {
    return null
  }
}

export async function setTimerState(
  sessionId: string,
  candidateId: string,
  state: TimerState
): Promise<void> {
  const ttl = state.durationSeconds + 7_200
  await getRedis().set(
    CANDIDATE_KEY(sessionId, candidateId),
    JSON.stringify(state),
    'EX',
    Math.max(ttl, 7_200)
  )
}

// ---------------------------------------------------------------------------
// Fan-out: apply a state mutation to ALL per-candidate timers for a session.
// Uses ioredis pipeline to batch reads and writes — keeps the round-trips
// to 2 regardless of how many candidates are in the session.
// ---------------------------------------------------------------------------

export async function fanOutToAllCandidates(
  sessionId: string,
  mutate: (state: TimerState, now: number) => TimerState
): Promise<void> {
  const redis = getRedis()

  // 1. Collect all candidate keys for this session
  const keys: string[] = []
  let cursor = '0'
  do {
    const [next, batch] = await redis.scan(
      cursor,
      'MATCH',
      CANDIDATE_SCAN_PATTERN(sessionId),
      'COUNT',
      500
    )
    cursor = next
    keys.push(...batch)
  } while (cursor !== '0')

  if (keys.length === 0) return

  const now = Date.now()

  // 2. Pipeline-read all current states
  const readPipeline = redis.pipeline()
  for (const key of keys) readPipeline.get(key)
  const readResults = await readPipeline.exec()

  // 3. Mutate and pipeline-write
  const writePipeline = redis.pipeline()
  readResults?.forEach(([err, raw], i) => {
    if (err || typeof raw !== 'string') return
    try {
      const current = JSON.parse(raw) as TimerState
      const next = mutate(current, now)
      const ttl = Math.max(next.durationSeconds + 7_200, 7_200)
      writePipeline.set(keys[i]!, JSON.stringify(next), 'EX', ttl)
    } catch {
      // Corrupt key — skip
    }
  })
  await writePipeline.exec()
}

// ---------------------------------------------------------------------------
// Scan all per-candidate timers (for DB sync)
// ---------------------------------------------------------------------------

export interface CandidateTimerEntry {
  sessionId: string
  candidateId: string
}

function parseCandidateKey(key: string): CandidateTimerEntry | null {
  // key = flextest:exam:timer:{sessionId}:{candidateId}
  const prefix = 'flextest:exam:timer:'
  if (!key.startsWith(prefix)) return null
  const rest = key.slice(prefix.length) // '{sessionId}:{candidateId}'
  const colonIdx = rest.indexOf(':')
  if (colonIdx === -1) return null      // old session-level key — ignore
  return {
    sessionId: rest.slice(0, colonIdx),
    candidateId: rest.slice(colonIdx + 1),
  }
}

export async function scanAllCandidateTimers(): Promise<CandidateTimerEntry[]> {
  const redis = getRedis()
  const entries: CandidateTimerEntry[] = []
  let cursor = '0'
  do {
    const [next, keys] = await redis.scan(
      cursor,
      'MATCH',
      ALL_CANDIDATES_SCAN_PATTERN,
      'COUNT',
      200
    )
    cursor = next
    for (const k of keys) {
      const parsed = parseCandidateKey(k)
      if (parsed) entries.push(parsed)
    }
  } while (cursor !== '0')
  return entries
}

// ---------------------------------------------------------------------------
// Distributed lock — ensures only ONE Next.js worker runs the 5-min DB sync
// ---------------------------------------------------------------------------

const SYNC_LOCK = 'flextest:exam:timer:sync:lock'

export async function acquireSyncLock(instanceId: string): Promise<boolean> {
  try {
    const result = await getRedis().set(SYNC_LOCK, instanceId, 'EX', 120, 'NX')
    return result === 'OK'
  } catch {
    return false
  }
}

const RELEASE_LUA = `
  if redis.call('get', KEYS[1]) == ARGV[1] then
    return redis.call('del', KEYS[1])
  end
  return 0
`

export async function releaseSyncLock(instanceId: string): Promise<void> {
  try {
    await getRedis().eval(RELEASE_LUA, 1, SYNC_LOCK, instanceId)
  } catch {
    // Non-fatal — TTL will expire the lock anyway
  }
}
